parameters.jsCode:
const form = $input.first().json;

const errors = [];

const topic = (form['Blog Topic'] || '').toString().trim();
if (!topic) errors.push('No blog topic provided.');

let wordCount = parseInt(form['Word Count'], 10);
if (isNaN(wordCount) || wordCount < 800) wordCount = 1200;
if (wordCount > 3000) wordCount = 3000;

const targetAudience = (form['Target Audience'] || '').toString().trim() || 'general readers';
const blogCategory = (form['Blog Category'] || '').toString().trim() || 'General';
const tone = (form['Tone'] || '').toString().trim() || 'professional yet conversational';

// ── Robust URL cleanup (no dependency on the URL class — some n8n sandboxes don't expose it) ──
let siteUrl = (form['WordPress Site URL'] || '').toString();

siteUrl = siteUrl
  .replace(/[\u200B-\u200D\uFEFF\u00A0]/g, '')   // zero-width & non-breaking spaces
  .replace(/[""'']/g, '')                          // curly quotes
  .replace(/[<>\[\]]/g, '')                          // stray brackets
  .trim();

if (!siteUrl) errors.push('No WordPress Site URL provided.');

// Auto-add https:// if the protocol was left off
if (siteUrl && !/^https?:\/\//i.test(siteUrl)) {
  siteUrl = 'https://' + siteUrl;
}

// Strip trailing slash(es)
siteUrl = siteUrl.replace(/\/+$/, '');

// Extract hostname via regex instead of the URL class
let siteDomain = '';
if (siteUrl) {
  const match = siteUrl.match(/^https?:\/\/([^\/\s?#]+)/i);
  if (match) {
    siteDomain = match[1].replace(/:\d+$/, '').replace(/^www\./i, '').toLowerCase();
  }
}

if (siteUrl && !siteDomain) {
  errors.push(`WordPress Site URL is not a valid URL. Received: "${siteUrl}"`);
}

if (errors.length) throw new Error(errors.join(' | '));

return [{ json: {
  primaryKeyword: topic.toLowerCase(),
  targetAudience,
  wordCount,
  blogCategory,
  tone,
  siteUrl,
  siteDomain,
  requestId: `blog_${Date.now()}_${Math.random().toString(36).slice(2,8)}`,
  timestamp: new Date().toISOString(),
  originalFormInput: form
}}];

const serpData = $input.first().json;
const organicResults = serpData.organic_results || [];
const prev = $node['Input Validation1'].json;
const siteDomain = prev.siteDomain || '';

const competitors = organicResults.slice(0, 10).map(r => ({
  position: r.position,
  title: r.title || '',
  snippet: r.snippet || '',
  link: r.link || ''
}));

const competitorCorpus = competitors.map(c => c.snippet).join(' ');

const allTitleWords = competitors
  .flatMap(c => c.title.toLowerCase().split(/[\s\-|:,]+/))
  .filter(w => w.length > 4);
const wordFreq = {};
allTitleWords.forEach(w => { wordFreq[w] = (wordFreq[w] || 0) + 1; });
const topCompetitorTerms = Object.entries(wordFreq)
  .sort((a,b) => b[1]-a[1])
  .slice(0, 15)
  .map(([word]) => word);

// Build real external link candidates from high-authority organic results,
// excluding the user's own site so we never "externally" link to ourselves.
function hostnameOf(url) {
  try { return new URL(url).hostname.replace(/^www\./, ''); } catch (e) { return ''; }
}
const externalLinkCandidates = competitors
  .filter(c => c.link && hostnameOf(c.link) && hostnameOf(c.link) !== siteDomain)
  .slice(0, 6)
  .map(c => ({ title: c.title, url: c.link, domain: hostnameOf(c.link) }));

return [{ json: {
  ...prev,
  serpData: { competitors, topCompetitorTerms, competitorCorpus: competitorCorpus.slice(0, 3000) },
  externalLinkCandidates
}}];

const posts = $input.all().map(item => item.json).filter(p => p && p.link);
const prev = $node['Parse SERP Data'].json;
const kw = (prev.primaryKeyword || '').toLowerCase();
const kwWords = kw.split(/\s+/).filter(w => w.length > 2);

function score(post) {
  const title = (post.title && post.title.rendered ? post.title.rendered : (post.title || '')).toLowerCase();
  const excerpt = (post.excerpt && post.excerpt.rendered ? post.excerpt.rendered : '').toLowerCase();
  let s = 0;
  if (title.includes(kw)) s += 10;
  kwWords.forEach(w => {
    if (title.includes(w)) s += 2;
    if (excerpt.includes(w)) s += 1;
  });
  return s;
}

const scored = posts
  .map(p => ({
    title: (p.title && p.title.rendered) ? p.title.rendered : (p.title || 'Untitled'),
    url: p.link,
    relevance: score(p)
  }))
  .filter(p => p.relevance > 0)
  .sort((a, b) => b.relevance - a.relevance)
  .slice(0, 8);

return [{ json: { ...prev, internalLinkCandidates: scored } }];

const raw = $input.first().json.output || $input.first().json.response || $input.first().json.text || '{}';
let parsed;
try {
  const cleaned = raw.replace(/```json|```/gi, '').trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  const kw = $node['Input Validation1'].json.primaryKeyword;
  parsed = {
    primaryKeyword: kw,
    semanticCluster: [],
    longTailKeywords: [],
    competitorGaps: [],
    searchIntent: 'informational',
    targetKeywordDensity: 1.5,
    seoTitle: kw.charAt(0).toUpperCase() + kw.slice(1) + ' — Complete Guide',
    metaDescription: 'Learn everything about ' + kw + ' in this comprehensive, expert-written guide.',
    slugUrl: kw.replace(/\s+/g,'-'),
    h1Tag: 'The Complete Guide to ' + kw.charAt(0).toUpperCase() + kw.slice(1),
    excerpt: 'Discover everything you need to know about ' + kw + ' in this in-depth guide written by experts.',
    sections: [
      { h2: 'What Is ' + kw.charAt(0).toUpperCase() + kw.slice(1) + '?', subsections: [] },
      { h2: 'Key Benefits of ' + kw.charAt(0).toUpperCase() + kw.slice(1), subsections: [{ h3: 'Why It Matters' }] },
      { h2: 'How to Get Started with ' + kw.charAt(0).toUpperCase() + kw.slice(1), subsections: [{ h3: 'Step-by-Step Approach' }] },
      { h2: 'Conclusion: ' + kw.charAt(0).toUpperCase() + kw.slice(1) + ' Final Thoughts', subsections: [] }
    ],
    faqQuestions: ['What is ' + kw + '?', 'How does ' + kw + ' work?', 'Why is ' + kw + ' important?'],
    tags: [kw],
    featuredImagePrompt: 'A business team discussing ' + kw + ' in a modern office, ' + 'clean modern corporate photography style, bright airy white/light background, professional business people or clean tech/office visuals, accented with TechBliss brand colors (blue #1E88E5 and amber #F5A623 used in UI/icon accents), polished SaaS-website aesthetic, no text overlay, 16:9 landscape'.replace(/'/g, ""),
    hookIntro: 'If you are searching for ' + kw + ', you already know how much is riding on getting it right.',
    ctaText: 'Want expert help with ' + kw + '? Get in touch with our team today.',
    inContentImagePrompts: [
      'A close-up of hands using a laptop showing ' + kw + ' related work, ' + 'clean modern corporate photography style, bright airy white/light background, professional business people or clean tech/office visuals, accented with TechBliss brand colors (blue #1E88E5 and amber #F5A623 used in UI/icon accents), polished SaaS-website aesthetic, no text overlay, 16:9 landscape'.replace(/'/g, ""),
      'Two professionals reviewing options for ' + kw + ' on a tablet or whiteboard, ' + 'clean modern corporate photography style, bright airy white/light background, professional business people or clean tech/office visuals, accented with TechBliss brand colors (blue #1E88E5 and amber #F5A623 used in UI/icon accents), polished SaaS-website aesthetic, no text overlay, 16:9 landscape'.replace(/'/g, ""),
      'A step-by-step workflow or checklist scene related to ' + kw + ' in a bright office, ' + 'clean modern corporate photography style, bright airy white/light background, professional business people or clean tech/office visuals, accented with TechBliss brand colors (blue #1E88E5 and amber #F5A623 used in UI/icon accents), polished SaaS-website aesthetic, no text overlay, 16:9 landscape'.replace(/'/g, "")
    ]
  };
}
const prev = $node['Add Money Page Links'].json;
return [{ json: { ...prev, outline: parsed } }];

parameters.text:
=You are an expert human content writer. Write a complete blog article of approximately {{ $node['Input Validation1'].json.wordCount }} words (focused, high-quality, 1200-1500 words - tight and no padding, agency-blog style).

Primary keyword: {{ $node['Input Validation1'].json.primaryKeyword }}
Audience: {{ $node['Input Validation1'].json.targetAudience }}
Tone: {{ $node['Input Validation1'].json.tone }}
Semantic keyword cluster (weave these in naturally): {{ $json.outline.semanticCluster.join(', ') }}
Competitor gaps to cover: {{ $json.outline.competitorGaps.join(', ') }}
Hook intro to open the article with (before H1 content, as first paragraph): {{ $json.outline.hookIntro }}
Mid-article CTA (insert as its own blockquote line starting with "CTA:" after roughly 40% of the article): {{ $json.outline.ctaText }}

Outline:
H1: {{ $json.outline.h1Tag }}
{{ $json.outline.sections.map((s,i) => '## ' + s.h2 + (s.includeTable ? ' [ADD A TABLE HERE]' : '') + (s.includeStatCallout ? ' [ADD A BLOCKQUOTE STAT CALLOUT HERE]' : '') + '\n' + (s.subsections||[]).map(ss => '### ' + ss.h3).join('\n')).join('\n') }}

FAQ questions to answer:
{{ $json.outline.faqQuestions.join('\n') }}

INTERNAL LINKS — naturally embed 2-3 of these as real Markdown links [anchor text](url) inside relevant sentences, spread across at least 2 different sections (never clustered together, never as a bare list at the end):
{{ ($json.internalLinkCandidates||[]).map(l => l.title + ' -> ' + l.url).join('\n') }}
For anchor text, prefer using the primary keyword or one of these secondary/longtail keywords naturally where it fits the sentence (don't force it if awkward): {{ $node['Input Validation1'].json.originalFormInput.SecondaryKeywords || '' }}

EXTERNAL LINKS — naturally embed 1-2 of these as real Markdown links [anchor text](url) citing sources/authority:
{{ ($json.externalLinkCandidates||[]).map(l => l.title + ' -> ' + l.url).join('\n') }}

STRICT MARKDOWN OUTPUT RULES (this is parsed by a Markdown-to-Gutenberg converter, follow EXACTLY):
1. H1 line starts with "# " and MUST contain the primary keyword exactly
2. First paragraph (100 words) MUST contain the primary keyword
3. At least 2 "## " headings must contain the primary keyword (including the conclusion)
4. Keyword density: 1.2%-2.0% — natural placement only, never stuffed
5. READABILITY IS CRITICAL - target a Flesch Reading Ease score of 60+ (plain, accessible English, not academic/dense writing):
   - Average sentence length 10-15 words. Break up any sentence over 20 words into two.
   - Use everyday words over complex/formal ones (e.g. "use" not "utilize", "help" not "facilitate", "show" not "demonstrate")
   - One idea per sentence. Avoid stacking multiple clauses with commas/semicolons.
   - Write like you're explaining it to a smart friend, not writing an academic paper
   - Vary sentence length for rhythm, but keep the AVERAGE short
6. Include 2-3 concrete real-world examples or analogies. Also weave in 1-2 authority/expertise signals naturally (E-E-A-T) - e.g. reference TechBliss's direct experience as a certified Google Workspace/Microsoft 365 partner, mention having helped real businesses (use realistic but non-specific framing like "we've guided dozens of SMBs through this exact decision" rather than inventing fake named companies or fake statistics). Write with the confident, first-hand voice of a practitioner who does this work daily, not a generic content writer.
7. Wherever a section is marked [ADD A TABLE HERE], insert a real HTML table directly under that heading using this exact structure (plain HTML, NOT markdown pipes):
   <table><thead><tr><th>Column A</th><th>Column B</th><th>Column C</th></tr></thead><tbody><tr><td>value 1</td><td>value 2</td><td>value 3</td></tr><tr><td>value 4</td><td>value 5</td><td>value 6</td></tr></tbody></table>
   Use 3-5 data rows relevant to that section. Never use markdown pipe syntax (|) for tables — always plain HTML <table> tags.
8. Wherever a section is marked [ADD A BLOCKQUOTE STAT CALLOUT HERE], insert a line starting with "> " containing a bolded statistic or key insight
9. Insert exactly 3 image placeholder lines at natural breaks between major sections (their own line, nothing else on the line): {{IMAGE_1}} then later {{IMAGE_2}} then later {{IMAGE_3}}
10. Insert the mid-article CTA as its own line: "> CTA: <the cta text>" after roughly 40% of the content
10b. In at least 2 different sections (not the same section as the CTA), add a short "Pro Tip" or "Key Insight" callout as its own line: "> TIP: <a genuinely useful, specific tip or insight related to that section — not generic filler>" — these render as amber-highlighted boxes and give the article visual rhythm, so spread them naturally through the middle sections
11. Add a "## Frequently Asked Questions" section with each question as "### " and the answer as a normal paragraph directly below it, covering ALL FAQ questions above. CRITICAL PLACEMENT: this FAQ section MUST appear immediately BEFORE the "## Conclusion" section — never after it. Order must be: [all body sections] -> FAQ -> Conclusion. Each FAQ answer should be a genuinely useful, specific 3-4 sentence paragraph (not a one-liner) — add real detail, examples, or numbers where relevant, not generic filler.
12. Use "- " bullet lists for scannable points (bold lead-in phrase via **text** + explanation), agency-blog style
13. End with a natural closing CTA paragraph inviting comments or next steps
14. BANNED phrases/style: 'delve into', 'in today's digital landscape', 'leverage', 'robust', 'it's worth noting', 'game-changer', 'unlock the power of'. Also avoid overly literary/flowery vocabulary (e.g. 'orchestrated', 'sprinkle', 'shepherd', 'tack on', 'crossroads', 'grasping the subtleties') — this isn't creative writing, it's a helpful business guide. Plain, direct, confident language only.
15. Return ONLY the markdown article — no code fences, no commentary, no HTML tags

parameters.jsCode:
const raw = $input.first().json.output || $input.first().json.response || '';
const prev = $node['Parse Outline'].json;
return [{ json: { ...prev, articleDraft: raw } }];

const raw = $input.first().json.output || $input.first().json.response || '';
const prev = $node['Store Draft'].json;
const original = prev.articleDraft || '';
// Guard: if the rewrite is suspiciously short (likely truncated mid-generation), keep the original instead
const isSuspiciouslyShort = raw && original && raw.trim().length < original.trim().length * 0.7;
const finalText = (raw && !isSuspiciouslyShort) ? raw : original;
return [{ json: { ...prev, articleFactChecked: finalText, factCheckTruncated: isSuspiciouslyShort } }];

const raw = $input.first().json.output || $input.first().json.response || '';
const prev = $node['Store Fact-Checked Article'].json;
const original = prev.articleFactChecked || '';
const isSuspiciouslyShort = raw && original && raw.trim().length < original.trim().length * 0.7;
const finalText = (raw && !isSuspiciouslyShort) ? raw : original;
return [{ json: { ...prev, articleSEO: finalText, seoPassTruncated: isSuspiciouslyShort } }];

const data = $input.first().json;
const article = data.articleSEO || '';
const corpus = (data.serpData && data.serpData.competitorCorpus) ? data.serpData.competitorCorpus : '';

if (!article || article.trim() === '') {
  return [{ json: { ...data, uniquenessScore: 0, uniquenessError: 'No article content' } }];
}

function termFreq(text) {
  const words = text.toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(w => w.length > 3);
  const freq = {};
  words.forEach(w => { freq[w] = (freq[w]||0) + 1; });
  return freq;
}

const articleTF = termFreq(article);
const corpusTF = termFreq(corpus);

function cosineSim(a, b) {
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  let dot = 0, magA = 0, magB = 0;
  keys.forEach(k => {
    const va = a[k]||0, vb = b[k]||0;
    dot += va*vb; magA += va*va; magB += vb*vb;
  });
  if (magA === 0 || magB === 0) return 0;
  return dot / (Math.sqrt(magA)*Math.sqrt(magB));
}

const similarity = corpus ? cosineSim(articleTF, corpusTF) : 0;
const uniquenessScore = Math.round(Math.max(0, Math.min(100, (1 - similarity) * 100)));

return [{ json: { ...data, uniquenessScore, competitorSimilarity: parseFloat(similarity.toFixed(3)) } }];

const data = $input.first().json;
const rewrite = data.output || data.response || data.text || '';
const base = data.serpData ? data : $node['Semantic Uniqueness Scoring'].json;
const original = base.articleSEO || '';
const isSuspiciouslyShort = rewrite && original && rewrite.trim().length < original.trim().length * 0.7;
const finalArticle = (rewrite && rewrite.trim().length > 200 && !isSuspiciouslyShort) ? rewrite : original;
return [{ json: { ...base, articleFinal: finalArticle, rewriteApplied: !!(rewrite && rewrite.trim().length > 200 && !isSuspiciouslyShort), uniquenessRewriteTruncated: isSuspiciouslyShort } }];

const data = $input.first().json;
const article = data.articleFinal || '';
if (!article.trim()) {
  return [{ json: { ...data, qcReport: { passedQC: false, error: 'No article content' } } }];
}

const kw = (data.primaryKeyword || '').toLowerCase().trim();
const semanticCluster = (data.outline && data.outline.semanticCluster) || [];
const siteDomain = data.siteDomain || '';

const words = article.split(/\s+/).filter(w => w.length > 0).length;
const articleLower = article.toLowerCase();
let kwOccurrences = 0;
let pos = 0;
while ((pos = articleLower.indexOf(kw, pos)) !== -1) { kwOccurrences++; pos += kw.length; }
const kwDensity = words > 0 ? parseFloat(((kwOccurrences / words) * 100).toFixed(2)) : 0;

const clusterCoverage = semanticCluster.length > 0
  ? semanticCluster.filter(t => articleLower.includes(t.toLowerCase())).length / semanticCluster.length
  : 1;

const h1Match = article.match(/^#\s+.+/m);
const hasKwInH1 = h1Match ? h1Match[0].toLowerCase().includes(kw) : false;
const h2Lines = [...article.matchAll(/^##\s+.+/gm)].map(m => m[0].toLowerCase());
const hasKwInH2 = h2Lines.some(l => l.includes(kw));
const conclusionMatch = article.match(/##[^#\n]*conclusion[\s\S]*$/im);
const hasKwInConclusion = conclusionMatch ? conclusionMatch[0].toLowerCase().includes(kw) : articleLower.slice(Math.floor(articleLower.length * 0.8)).includes(kw);

const sentences = article.split(/[.!?]+/).filter(s => s.trim().length > 5);
const avgWords = words / Math.max(1, sentences.length);
const syllables = (article.match(/[aeiouy]/gi) || []).length;
const avgSyll = syllables / Math.max(1, words);
const flesch = Math.max(0, Math.min(100, Math.round(206.835 - 1.015 * avgWords - 84.6 * avgSyll)));

// ── Link checks ──────────────────────────────────────────────
const mdLinks = [...article.matchAll(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g)].map(m => ({ anchor: m[1], url: m[2] }));
function hostnameOf(url) { try { return new URL(url).hostname.replace(/^www\./, ''); } catch (e) { return ''; } }
const internalLinks = siteDomain ? mdLinks.filter(l => hostnameOf(l.url) === siteDomain) : [];
const externalLinks = siteDomain ? mdLinks.filter(l => hostnameOf(l.url) && hostnameOf(l.url) !== siteDomain) : mdLinks;
const hasInternalLink = internalLinks.length > 0 || (data.internalLinkCandidates || []).length === 0;
const hasExternalLink = externalLinks.length > 0 || (data.externalLinkCandidates || []).length === 0;

const seoScore = (hasKwInH1 ? 25 : 0) + (hasKwInH2 ? 25 : 0) + (hasKwInConclusion ? 25 : 0) +
  (kwDensity >= 1.0 && kwDensity <= 2.2 ? 25 : kwDensity >= 0.7 ? 12 : 0);

const semanticBonus = Math.round(clusterCoverage * 20);
const readabilityBonus = flesch >= 50 ? 10 : 0;
const hasCTA = /^>\s*CTA:/im.test(article);
const hasFAQ = /\b(faq|frequently asked|people also ask)\b/i.test(article);
const overallScore = Math.min(100, Math.round(seoScore * 0.6 + semanticBonus * 0.2 + readabilityBonus * 0.1 + (hasCTA ? 5 : 0) + (hasFAQ ? 5 : 0)));
const passedQC = seoScore >= 75 && kwDensity >= 1.0 && kwDensity <= 2.2 && hasKwInH1 && hasInternalLink && hasExternalLink;

return [{ json: { ...data, qcReport: {
  wordCount: words, keywordDensity: kwDensity, keywordOccurrences: kwOccurrences,
  readabilityScore: flesch, seoScore, semanticClusterCoverage: parseFloat(clusterCoverage.toFixed(2)),
  semanticBonus, overallScore, hasCTA, hasFAQ,
  keywordPlacement: { inH1: hasKwInH1, inH2: hasKwInH2, inConclusion: hasKwInConclusion },
  internalLinkCount: internalLinks.length, externalLinkCount: externalLinks.length,
  hasInternalLink, hasExternalLink,
  passedQC
}}}];

const fixed = $input.first().json.output || $input.first().json.response || '';
const prev = $node['Quality Validation1'].json;
const original = prev.articleFinal || '';
const isSuspiciouslyShort = fixed && original && fixed.trim().length < original.trim().length * 0.7;
const finalText = (fixed && !isSuspiciouslyShort) ? fixed : original;
return [{ json: { ...prev, articleFinal: finalText, qcFixApplied: !isSuspiciouslyShort, qcFixTruncated: isSuspiciouslyShort } }];

const data = $input.first().json;
const article = data.articleFinal || '';
if (!article.trim()) return [{ json: { ...data, qcReport: { passedQC: false, error: 'No article after fix' } } }];

const kw = (data.primaryKeyword || '').toLowerCase().trim();
const siteDomain = data.siteDomain || '';
const words = article.split(/\s+/).filter(w => w.length > 0).length;
const articleLower = article.toLowerCase();
let kwOcc = 0, pos = 0;
while ((pos = articleLower.indexOf(kw, pos)) !== -1) { kwOcc++; pos += kw.length; }
const kwDensity = words > 0 ? parseFloat(((kwOcc/words)*100).toFixed(2)) : 0;
const h1Match = article.match(/^#\s+.+/m);
const hasKwInH1 = h1Match ? h1Match[0].toLowerCase().includes(kw) : false;
const h2Lines = [...article.matchAll(/^##\s+.+/gm)].map(m => m[0].toLowerCase());
const hasKwInH2 = h2Lines.some(l => l.includes(kw));
const conclusionMatch = article.match(/##[^#\n]*conclusion[\s\S]*$/im);
const hasKwInConclusion = conclusionMatch ? conclusionMatch[0].toLowerCase().includes(kw) : articleLower.slice(Math.floor(articleLower.length*0.8)).includes(kw);

const mdLinks = [...article.matchAll(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g)].map(m => ({ anchor: m[1], url: m[2] }));
function hostnameOf(url) { try { return new URL(url).hostname.replace(/^www\./, ''); } catch (e) { return ''; } }
const internalLinks = siteDomain ? mdLinks.filter(l => hostnameOf(l.url) === siteDomain) : [];
const externalLinks = siteDomain ? mdLinks.filter(l => hostnameOf(l.url) && hostnameOf(l.url) !== siteDomain) : mdLinks;
const hasInternalLink = internalLinks.length > 0 || (data.internalLinkCandidates || []).length === 0;
const hasExternalLink = externalLinks.length > 0 || (data.externalLinkCandidates || []).length === 0;

const seoScore = (hasKwInH1?25:0)+(hasKwInH2?25:0)+(hasKwInConclusion?25:0)+(kwDensity>=1&&kwDensity<=2.2?25:kwDensity>=0.7?12:0);
const hasCTA = /^>\s*CTA:/im.test(article);
const hasFAQ = /\b(faq|frequently asked|people also ask)\b/i.test(article);
const passedQC = seoScore >= 75 && kwDensity >= 1.0 && kwDensity <= 2.2 && hasKwInH1 && hasInternalLink && hasExternalLink;
return [{ json: { ...data, qcReport: { wordCount:words, keywordDensity:kwDensity, keywordOccurrences:kwOcc, seoScore, hasCTA, hasFAQ, internalLinkCount: internalLinks.length, externalLinkCount: externalLinks.length, hasInternalLink, hasExternalLink, keywordPlacement:{inH1:hasKwInH1,inH2:hasKwInH2,inConclusion:hasKwInConclusion}, passedQC } } }];

// ============================================================
// PREPARE WORDPRESS POST
// Converts Markdown -> Gutenberg HTML blocks
// Resolves standard Markdown links [text](url) into real <a> tags
// (both internal links to existing site posts and external
// authority links resolved earlier in the workflow)
// Injects Yoast SEO meta fields, tags, excerpt, slug
// ============================================================
const data = $input.first().json;
// Strip any leftover instruction-marker text the AI failed to remove after inserting the
// actual content (e.g. "[ADD A TABLE HERE]" is a placeholder telling the AI where to put a
// table - it should be replaced entirely, but sometimes gets left behind as literal visible text).
const rawMarkdown = data.articleFinal || '';
const markdown = rawMarkdown
  .replace(/\[ADD A TABLE HERE\]/gi, '')
  .replace(/\[ADD A BLOCKQUOTE STAT CALLOUT HERE\]/gi, '')
  .replace(/\[ADD A MARKDOWN TABLE HERE\]/gi, '')
  .replace(/[ \t]+\n/g, '\n'); // clean up any trailing whitespace left behind on those lines
const kw = data.primaryKeyword || 'blog';
const outline = data.outline || {};
const qcReport = data.qcReport || {};

// ── 1. MARKDOWN -> GUTENBERG HTML ─────────────────────────────
// ── TABLE OF CONTENTS PRE-SCAN ──────────────────────────────────
// Scans the raw markdown once for every H2/H3 heading, assigning each a unique slug.
// This same ordered list is consumed (in order) during the actual heading rendering below,
// so the TOC links and the real heading IDs always match exactly.
function buildHeadingList(md) {
  const usedSlugs = new Set();
  const list = [];
  md.split('\n').forEach(line => {
    const h2 = line.match(/^##\s+(.+)$/);
    const h3 = line.match(/^###\s+(.+)$/);
    if (h2 && !line.startsWith('###')) {
      const text = h2[1].trim();
      let base = text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
      let slug = base, n = 2;
      while (usedSlugs.has(slug)) { slug = `${base}-${n}`; n++; }
      usedSlugs.add(slug);
      list.push({ level: 2, text, slug });
    } else if (h3 && !line.startsWith('####')) {
      const text = h3[1].trim();
      let base = text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
      let slug = base, n = 2;
      while (usedSlugs.has(slug)) { slug = `${base}-${n}`; n++; }
      usedSlugs.add(slug);
      list.push({ level: 3, text, slug });
    }
  });
  return list;
}

function buildTocHtml(headingList) {
  if (!headingList.length) return '';
  // Show all H2s flat, but only show H3s if they fall inside the FAQ section
  // (matches the reference design - regular body subsections don't clutter the TOC).
  let insideFaq = false;
  const tocEntries = headingList.filter(h => {
    if (h.level === 2) {
      insideFaq = /frequently asked questions|^faq/i.test(h.text);
      return true;
    }
    return insideFaq; // H3s only kept while inside the FAQ section
  });

  // Build as plain nested <ul><li> HTML - FAQ sub-questions nest inside their parent <li>
  // so it reads as one continuous native WordPress list, not two separate lists.
  let listItems = '';
  let i = 0;
  while (i < tocEntries.length) {
    const h = tocEntries[i];
    if (h.level === 2) {
      const isFaqHeading = /frequently asked questions|^faq/i.test(h.text);
      let nested = '';
      if (isFaqHeading) {
        let j = i + 1;
        const subItems = [];
        while (j < tocEntries.length && tocEntries[j].level === 3) {
          subItems.push(`<li><a href="#${tocEntries[j].slug}">${tocEntries[j].text}</a></li>`);
          j++;
        }
        if (subItems.length) nested = `<ul>${subItems.join('')}</ul>`;
        i = j;
      } else {
        i++;
      }
      listItems += `<li><a href="#${h.slug}">${h.text}</a>${nested}</li>`;
    } else {
      i++;
    }
  }
  listItems += '<li><a href="#get-a-free-quote">Get a Free Quote</a></li>';

  // Native WordPress "Details" block (wp:details, WP 6.4+) - real collapsible <details>/<summary>
  // HTML, expands/collapses natively in every browser with no custom JS needed.
  return `<!-- wp:details {"summary":"Table of Contents"} -->
<details class="wp-block-details"><summary>Table of Contents</summary>
<!-- wp:list -->
<ul class="wp-block-list">${listItems}</ul>
<!-- /wp:list -->
</details>
<!-- /wp:details -->`;
}

function markdownToGutenberg(md) {
  const headingQueue = buildHeadingList(md).slice(); // consumed in order as headings are rendered below
  // Safety net: pull ANY <table>...</table> block out wherever it appears (even mid-sentence,
  // even inline with intro text) and force it onto its own isolated lines, so the line-by-line
  // parser below always catches it as a real table instead of it falling through to escaped text.
  md = md.replace(/<table[\s\S]*?<\/table>/gi, (tableHtml) => `\n\n${tableHtml}\n\n`);

  // Safety net: if the AI squished a whole table onto one line (e.g. "| A | B | |—|—| | 1 | 2 |"),
  // split it back into separate rows so it never renders as raw garbled pipe text.
  md = md.replace(/(\|[^\n]*\|)/g, (block) => {
    const pipeCount = (block.match(/\|/g) || []).length;
    if (pipeCount <= 6) return block; // looks like one normal row already, leave it alone
    // Break the line wherever a "|" closes one cell and immediately opens the next row
    // (heuristic: insert a newline before every "|" that follows a "|" + optional space + a capitalized word/number,
    // once we've already seen a separator-style segment like |---| or |—|)
    if (!/\|\s*[-—]+\s*\|/.test(block)) return block; // no separator row detected, probably not a squished table
    return block.replace(/\|\s*(?=[A-Z0-9])/g, '|\n');
  });
  const lines = md.split('\n');
  const blocks = [];
  let i = 0;

  while (i < lines.length) {
    const loopStartI = i;
    const line = lines[i];

    if (line.trim() === '') { i++; continue; }

    // Skip the article's own "# H1" line entirely - WordPress's post title (set via the
    // "title" field below, using seoTitle) is already rendered as the page's single real <h1>
    // by the theme. Rendering a second <h1> here duplicated it visually and hurt on-page SEO
    // (duplicate H1 tags). The line is still present in the underlying markdown for QC checks,
    // just not converted into a heading block in the actual post body.
    if (/^#\s/.test(line) && !/^##/.test(line)) {
      i++; continue;
    }

    if (/^##\s/.test(line) && !/^###/.test(line)) {
      const rawText = line.replace(/^##\s+/, '');
      const text = inlineFormat(rawText);
      const headingEntry = headingQueue.shift();
      const id = headingEntry ? headingEntry.slug : '';
      blocks.push(`<!-- wp:heading {"level":2} -->\n<h2 class="wp-block-heading" id="${id}">${text}</h2>\n<!-- /wp:heading -->`);
      i++; continue;
    }

    if (/^###\s/.test(line) && !/^####/.test(line)) {
      const rawText = line.replace(/^###\s+/, '');
      const text = inlineFormat(rawText);
      const headingEntry = headingQueue.shift();
      const id = headingEntry ? headingEntry.slug : '';
      blocks.push(`<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading" id="${id}">${text}</h3>\n<!-- /wp:heading -->`);
      i++; continue;
    }

    // H4/H5/H6 (4+ hashes) - the AI isn't instructed to use these, but if it ever does,
    // render as a bold paragraph rather than falling through unhandled (which caused an
    // infinite loop: these lines matched the paragraph-collector's exclusion pattern but
    // had no explicit handler, so `i` never advanced and the loop spun forever).
    if (/^#{4,6}\s/.test(line)) {
      const rawText = line.replace(/^#{4,6}\s+/, '');
      const text = inlineFormat(rawText);
      blocks.push(`<!-- wp:paragraph -->\n<p><strong>${text}</strong></p>\n<!-- /wp:paragraph -->`);
      i++; continue;
    }

    if (/^-\s/.test(line)) {
      const items = [];
      while (i < lines.length && /^-\s/.test(lines[i])) {
        items.push(`<li>${inlineFormat(lines[i].replace(/^-\s+/, ''))}</li>`);
        i++;
      }
      blocks.push(`<!-- wp:list -->\n<ul class="wp-block-list">\n${items.join('\n')}\n</ul>\n<!-- /wp:list -->`);
      continue;
    }

    if (/^\d+\.\s/.test(line)) {
      const items = [];
      while (i < lines.length && /^\d+\.\s/.test(lines[i])) {
        items.push(`<li>${inlineFormat(lines[i].replace(/^\d+\.\s+/, ''))}</li>`);
        i++;
      }
      blocks.push(`<!-- wp:list {"ordered":true} -->\n<ol class="wp-block-list">\n${items.join('\n')}\n</ol>\n<!-- /wp:list -->`);
      continue;
    }

    // CTA callout: "> CTA: text"
    if (/^>\s*CTA:\s*/.test(line)) {
      const text = inlineFormat(line.replace(/^>\s*CTA:\s*/, ''));
      blocks.push(`<!-- wp:group {"className":"cta-box"} --><div class="wp-block-group cta-box" style="border-left:4px solid #1E88E5;padding:16px 20px;background:#eaf4fd;margin:24px 0;border-radius:4px;"><p style="margin:0;"><strong>💡 ${text}</strong></p></div><!-- /wp:group -->`);
      i++; continue;
    }

    // Tip/highlight callout: "> TIP: text" - amber, visually distinct from the blue CTA box
    if (/^>\s*TIP:\s*/.test(line)) {
      const text = inlineFormat(line.replace(/^>\s*TIP:\s*/, ''));
      blocks.push(`<!-- wp:group {"className":"tip-box"} --><div class="wp-block-group tip-box" style="border-left:4px solid #F5A623;padding:16px 20px;background:#fff8ec;margin:24px 0;border-radius:4px;"><p style="margin:0;"><strong>⭐ Pro Tip:</strong> ${text}</p></div><!-- /wp:group -->`);
      i++; continue;
    }

    if (/^>\s/.test(line)) {
      // Stat/insight callout - third distinct visual style (dark card), separate from CTA (blue) and TIP (amber)
      const text = inlineFormat(line.replace(/^>\s+/, ''));
      blocks.push(`<!-- wp:group {"className":"stat-callout"} --><div class="wp-block-group stat-callout" style="background:#1a1a2e;color:#fff;padding:20px 24px;margin:24px 0;border-radius:6px;"><p style="margin:0;font-size:1.1em;">📊 ${text}</p></div><!-- /wp:group -->`);
      i++; continue;
    }

    if (/^---+$/.test(line.trim())) {
      blocks.push(`<!-- wp:separator -->\n<hr class="wp-block-separator has-alpha-channel-opacity"/>\n<!-- /wp:separator -->`);
      i++; continue;
    }

    // Real HTML <table> block (preferred format) -> pass straight through as wp:table
    if (/^<table/i.test(line.trim())) {
      let tableHtml = '';
      while (i < lines.length && !/<\/table>/i.test(lines[i])) { tableHtml += lines[i] + '\n'; i++; }
      if (i < lines.length) { tableHtml += lines[i]; i++; } // include the closing </table> line itself
      blocks.push(`<!-- wp:table --><figure class="wp-block-table">${tableHtml}</figure><!-- /wp:table -->`);
      continue;
    }

    // GFM Markdown table -> wp:table block
    if (/^\|.+\|\s*$/.test(line) && i + 1 < lines.length && /^\|[\s:\-|]+\|\s*$/.test(lines[i+1])) {
      const headerCells = line.split('|').map(c => c.trim()).filter((c,idx,arr) => !(idx===0 && c==='') && !(idx===arr.length-1 && c===''));
      i += 2;
      const rows = [];
      while (i < lines.length && /^\|.+\|\s*$/.test(lines[i])) {
        const cells = lines[i].split('|').map(c => c.trim()).filter((c,idx,arr) => !(idx===0 && c==='') && !(idx===arr.length-1 && c===''));
        rows.push(cells);
        i++;
      }
      const thead = `<thead><tr>${headerCells.map(h => `<th>${inlineFormat(h)}</th>`).join('')}</tr></thead>`;
      const tbody = `<tbody>${rows.map(r => `<tr>${r.map(c => `<td>${inlineFormat(c)}</td>`).join('')}</tr>`).join('')}</tbody>`;
      blocks.push(`<!-- wp:table --><figure class="wp-block-table"><table>${thead}${tbody}</table></figure><!-- /wp:table -->`);
      continue;
    }

    // In-content image placeholders {{IMAGE_1}} / {{IMAGE_2}} / {{IMAGE_3}}
    if (/^\{\{IMAGE_(\d+)\}\}\s*$/.test(line.trim())) {
      const idx = line.trim().match(/^\{\{IMAGE_(\d+)\}\}$/)[1];
      const imgList = data.inContentImages || [];
      const img = imgList[parseInt(idx,10) - 1];
      if (img && img.url) {
        blocks.push(`<!-- wp:image {"sizeSlug":"large"} --><figure class="wp-block-image size-large"><img src="${img.url}" alt="${(img.alt||kw).replace(/"/g,'')}"/></figure><!-- /wp:image -->`);
      }
      i++; continue;
    }

    // Legacy placeholder support (in case an agent still emits the old format)
    if (/^\[Internal Link:/.test(line) || /^\[External Link:/.test(line)) {
      const text = inlineFormat(line);
      blocks.push(`<!-- wp:paragraph -->\n<p>${text}</p>\n<!-- /wp:paragraph -->`);
      i++; continue;
    }

    const paraLines = [];
    while (
      i < lines.length &&
      lines[i].trim() !== '' &&
      !/^#{1,6}\s/.test(lines[i]) &&
      !/^-\s/.test(lines[i]) &&
      !/^\d+\.\s/.test(lines[i]) &&
      !/^>\s/.test(lines[i]) &&
      !/^---+$/.test(lines[i].trim())
    ) {
      paraLines.push(lines[i]);
      i++;
    }
    if (paraLines.length > 0) {
      const text = inlineFormat(paraLines.join(' '));
      blocks.push(`<!-- wp:paragraph -->\n<p>${text}</p>\n<!-- /wp:paragraph -->`);
    }

    // HARD SAFETY NET: if nothing above advanced `i` for this line (an unhandled edge case
    // we haven't anticipated), force it forward as a last resort so the loop can NEVER hang
    // indefinitely. Better to skip one weird line than freeze the whole workflow.
    if (i === loopStartI) { i++; }
  }

  // Insert the Table of Contents right at the top of the body (after any intro paragraph
  // that came before the first heading, so it doesn't awkwardly sit above the hook).
  const tocHtml = buildTocHtml(buildHeadingList(md));
  if (tocHtml) {
    const firstHeadingBlockIndex = blocks.findIndex(b => b.includes('wp:heading'));
    if (firstHeadingBlockIndex > 0) {
      blocks.splice(firstHeadingBlockIndex, 0, tocHtml);
    } else {
      blocks.unshift(tocHtml);
    }
  }

  return blocks.join('\n\n');
}

// Inline formatting (real markdown links, bold, italic, code, legacy placeholders)
function inlineFormat(text) {
  // Escape HTML entities first (avoid double-encoding)
  text = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

  // Real Markdown links [anchor text](https://url) -> resolved <a> tags.
  // Internal vs external is decided purely by comparing the link's domain
  // to the site's own domain (siteDomain), so no manual tagging is needed.
  text = text.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (m, anchor, url) => {
    let hostname = '';
    try { hostname = new URL(url).hostname.replace(/^www\./, ''); } catch (e) {}
    const isInternal = data.siteDomain && hostname === data.siteDomain;
    const relAttr = isInternal ? '' : ' target="_blank" rel="noopener noreferrer nofollow"';
    return `<a href="${url}"${relAttr}>${anchor}</a>`;
  });

  // Bold **text**
  text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  // Italic *text* (not already inside <strong>)
  text = text.replace(/(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*)/g, '<em>$1</em>');
  // Inline code `text`
  text = text.replace(/`([^`]+)`/g, '<code>$1</code>');

  // Legacy placeholder fallback (only triggers if the agent didn't resolve to real Markdown links)
  text = text.replace(/\[Internal Link:\s*([^\]]+)\]/g, '<a href="#">$1</a>');
  text = text.replace(/\[External Link:\s*(https?:\/\/[^\s\-\]]+)[\s\-\u2014][^\]]*\]/g, '<a href="$1" target="_blank" rel="noopener noreferrer nofollow">$1</a>');

  return text;
}

const gutenbergContent = markdownToGutenberg(markdown);

// ── 3. SEO FIELDS ─────────────────────────────────────────────
// Truncate cleanly at a word boundary (never mid-word), and only add "..." if we actually cut something.
function truncateClean(text, maxLen) {
  if (!text || text.length <= maxLen) return text;
  const cut = text.slice(0, maxLen);
  const lastSpace = cut.lastIndexOf(' ');
  const clean = lastSpace > 0 ? cut.slice(0, lastSpace) : cut;
  return clean.replace(/[,;:\-–—]+$/, '').trim() + '…';
}

