const usedUrls = new Set();

// ---------- 1. Fix/strip invalid links, track which real ones survive and where ----------
article = article.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (match, anchor, url) => {
  const normalized = url.replace(/^https?:\/\/(www\.)?/, 'https://');
  if (REAL_LANDING_PAGES.has(normalized) || REAL_LANDING_PAGES.has(url)) {
    usedUrls.add(normalized);
    return match;
  }
  return anchor;
});

// ---------- 1b. Strip leftover raw link-dump clutter (redundant with the Explore Services section) ----------
// Removes lines that are mostly just pipe-separated links with little else, and any
// "External reference: ..." labels the AI sometimes leaves as plain unlinked text.
article = article
  .split('\n')
  .filter(line => {
    const trimmed = line.trim();
    if (/^external reference:/i.test(trimmed)) return false;
    // A line that's 2+ markdown links joined mostly by "|" and almost nothing else
    const linkCount = (trimmed.match(/\[[^\]]+\]\([^)]+\)/g) || []).length;
    const strippedOfLinks = trimmed.replace(/\[[^\]]+\]\([^)]+\)/g, '').replace(/[\s|]/g, '');
    if (linkCount >= 2 && strippedOfLinks.length === 0) return false;
    return true;
  })
  .join('\n');

// ---------- 2. Split into H2 sections, remove duplicates ----------
const sectionRegex = /(?=^##\s)/m;
const sections = article.split(sectionRegex).filter(s => s.length > 0);
let preamble = '';
let h2Sections = sections;
if (sections.length && !/^##\s/.test(sections[0])) {
  preamble = sections[0];
  h2Sections = sections.slice(1);
}

// ---------- 2b. Make the primary keyword itself a hyperlink in the opening paragraph ----------
// Handles BOTH cases: the keyword appears as plain text, OR already wrapped in **bold** markers
// (very common, since the SEO rules ask the writer to bold the keyword on first use).
// Either way it ends up as a real clickable link - bold+linked if it was bold, plain-linked otherwise.
const preambleHasRealLink = [...usedUrls].some(u => preamble.includes(u));
if (!preambleHasRealLink && (data.internalLinkCandidates || []).length > 0) {
  const firstCandidate = data.internalLinkCandidates.find(c => !usedUrls.has(c.url));
  const primaryKeyword = (data.primaryKeyword || '').trim();

  if (firstCandidate && preamble.trim().length > 0) {
    let linked = false;
    if (primaryKeyword) {
      const escaped = primaryKeyword.replace(/[.*+?^\${}()|[\]\\]/g, '\\$&');

      // Restrict the search to just the FIRST 2 SENTENCES of the preamble (not the whole intro) -
      // the keyword should be highlighted/linked early, not buried several sentences in.
      const sentenceSplit = preamble.match(/[^.!?]+[.!?]+/g) || [preamble];
      const firstTwoLen = sentenceSplit.slice(0, 2).join('').length;
      const earlyPart = preamble.slice(0, firstTwoLen);
      const restPart = preamble.slice(firstTwoLen);

      const boldKwRegex = new RegExp(`\\*\\*(${escaped})\\*\\*`, 'i');
      const plainKwRegex = new RegExp(`(?<!\\[)\\b(${escaped})\\b(?![^\\[]*\\])`, 'i');

      if (boldKwRegex.test(earlyPart)) {
        const newEarly = earlyPart.replace(boldKwRegex, (match, inner) => `**[${inner}](${firstCandidate.url})**`);
        preamble = newEarly + restPart;
        usedUrls.add(firstCandidate.url);
        linked = true;
      } else if (plainKwRegex.test(earlyPart)) {
        const newEarly = earlyPart.replace(plainKwRegex, (match) => `[${match}](${firstCandidate.url})`);
        preamble = newEarly + restPart;
        usedUrls.add(firstCandidate.url);
        linked = true;
      }
    }
    // Fallback: keyword phrase wasn't found in the first 2 sentences - add a natural linking sentence instead
    if (!linked) {
      preamble = preamble.trimEnd() + `\n\nLearn more in our [${firstCandidate.title}](${firstCandidate.url}) guide.\n\n`;
      usedUrls.add(firstCandidate.url);
    }
  }
}

const seenHeadings = new Set();
h2Sections = h2Sections.filter(s => {
  const headingMatch = s.match(/^##\s*(.+)$/m);
  if (!headingMatch) return true;
  const normalized = headingMatch[1].toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  if (seenHeadings.has(normalized)) return false;
  seenHeadings.add(normalized);
  return true;
});

// ---------- 3. Force real links at evenly-spread intervals ----------
// Excludes FAQ/Conclusion sections as insertion targets (a link doesn't belong in the closing sections).
const candidates = (data.internalLinkCandidates || []).filter(c => !usedUrls.has(c.url));
const isFaqOrConclusion = (s) => /^##\s*(Frequently Asked Questions|FAQ)/im.test(s) || /^##[^\n]*conclusion/im.test(s);
const eligibleIndexes = h2Sections.map((s, i) => i).filter(i => !isFaqOrConclusion(h2Sections[i]));

if (candidates.length > 0 && eligibleIndexes.length > 0) {
  const targetCount = Math.min(candidates.length, eligibleIndexes.length); // one link per eligible section, not capped at 4
  const interval = Math.max(1, Math.floor(eligibleIndexes.length / targetCount));
  let candidateIdx = 0;

  for (let i = 0; i < targetCount; i++) {
    const sectionArrayIndex = eligibleIndexes[Math.min(i * interval, eligibleIndexes.length - 1)];
    const candidate = candidates[candidateIdx];
    if (!candidate) break;
    candidateIdx++;

    const sectionText = h2Sections[sectionArrayIndex];
    // Only add if this section doesn't already have a real link in it
    const hasRealLinkAlready = [...usedUrls].some(u => sectionText.includes(u));
    if (!hasRealLinkAlready) {
      const sentence = `\n\nFor more on this, see our [${candidate.title}](${candidate.url}) page.\n\n`;
      h2Sections[sectionArrayIndex] = sectionText.trimEnd() + sentence;
      usedUrls.add(candidate.url);
    }
  }
}

// ---------- 4. Force FAQ to sit immediately before Conclusion ----------
const faqIndex = h2Sections.findIndex(s => /^##\s*(Frequently Asked Questions|FAQ)/im.test(s));
const conclusionIndex = h2Sections.findIndex(s => /^##[^\n]*conclusion/im.test(s));

if (faqIndex !== -1 && conclusionIndex !== -1 && faqIndex > conclusionIndex) {
  const faqBlock = h2Sections[faqIndex];
  h2Sections.splice(faqIndex, 1);
  const newConclusionIndex = h2Sections.findIndex(s => /^##[^\n]*conclusion/im.test(s));
  h2Sections.splice(newConclusionIndex, 0, faqBlock);
}

article = preamble + h2Sections.join('');

return [{ json: { ...data, articleFinal: article } }];
